import React, { useEffect, useMemo, useState } from 'react';

const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];
const WEEKDAYS = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];

// Неделя (Пн–Вс), в которую попадает сегодня
const getWeekDays = () => {
  const now = new Date();
  const monday = new Date(now);
  monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return d;
  });
};

const isSameDay = (a, b) =>
  a.getDate() === b.getDate() &&
  a.getMonth() === b.getMonth() &&
  a.getFullYear() === b.getFullYear();

/*
  ВРЕМЕННАЯ ЗАГЛУШКА QR для вёрстки.
  TODO: заменить на <img src={qrUrl} /> — реальный QR приходит с backend
  и обновляется каждые 3–5 минут.
*/
const FakeQr = () => {
  const size = 21;
  const cells = useMemo(() => {
    let seed = 42;
    const rand = () => {
      seed = (seed * 1664525 + 1013904223) % 4294967296;
      return seed / 4294967296;
    };
    const inFinder = (x, y) =>
      (x < 7 && y < 7) || (x >= size - 7 && y < 7) || (x < 7 && y >= size - 7);
    const result = [];
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (!inFinder(x, y) && rand() > 0.5) result.push([x, y]);
      }
    }
    return result;
  }, []);

  const finder = (fx, fy) => (
    <g key={`${fx}-${fy}`}>
      <rect x={fx} y={fy} width={7} height={7} fill="#0D0C0C" />
      <rect x={fx + 1} y={fy + 1} width={5} height={5} fill="#F2F2F7" />
      <rect x={fx + 2} y={fy + 2} width={3} height={3} fill="#0D0C0C" />
    </g>
  );

  return (
    <svg viewBox="0 0 21 21" shapeRendering="crispEdges" className="h-full w-full" aria-label="QR-код выдачи">
      <rect width="21" height="21" fill="#F2F2F7" />
      {cells.map(([x, y]) => (
        <rect key={`${x}-${y}`} x={x} y={y} width="1" height="1" fill="#0D0C0C" />
      ))}
      {finder(0, 0)}
      {finder(14, 0)}
      {finder(0, 14)}
    </svg>
  );
};

const StaffQr = () => {
  const today = new Date();
  const weekDays = getWeekDays();

  // TODO: приходит с backend (polling / websocket) после выдачи питания
  // Для отладки оверлея поставь: useState({ name: 'Александра Иванова', group: '18-116' })
  const [issuedStudent, setIssuedStudent] = useState(null);

  // TODO: счётчик порций приходит с backend
  const [issuedCount, setIssuedCount] = useState(101);

  // Оверлей успеха показывается несколько секунд и скрывается
  useEffect(() => {
    if (!issuedStudent) return undefined;
    const timer = setTimeout(() => setIssuedStudent(null), 4000);
    return () => clearTimeout(timer);
  }, [issuedStudent]);

  return (
    <div className="relative min-h-screen w-full bg-secondary flex flex-col px-5">
      <div className="mx-auto flex w-full max-w-[960px] flex-1 flex-col">

        {/* Шапка: логотип + меню */}
        <header className="flex items-center justify-between pt-6 laptop:pt-8">
          {/* TODO: заменить на брендовый ассет логотипа */}
          <div className="flex items-center gap-3">
            <svg width="40" height="40" viewBox="0 0 24 24" fill="#0D0C0C" aria-hidden>
              <path d="M2 4 L22 12 L2 20 L8 12 Z" />
            </svg>
            <span className="text-2xl font-semibold text-black laptop:text-[32px]">
              Талон
            </span>
          </div>
          <button
            type="button"
            aria-label="Меню"
            onClick={() => {
              // TODO: открыть меню (выход, настройки — см. вопрос ниже)
            }}
            className="p-2 text-black"
          >
            <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
              <circle cx="5" cy="12" r="2" />
              <circle cx="12" cy="12" r="2" />
              <circle cx="19" cy="12" r="2" />
            </svg>
          </button>
        </header>

        {/* Месяц + иконка календаря */}
        <div className="mt-10 flex items-center justify-between laptop:mt-16">
          <h1 className="text-4xl leading-[105%] font-semibold text-black laptop:text-[64px] desktop:text-[32px]">
            {MONTHS[today.getMonth()]} {today.getFullYear()}
          </h1>
          <button
            type="button"
            aria-label="Открыть календарь"
            onClick={() => {
              // TODO: открыть календарь (см. вопрос ниже)
            }}
            className="p-2 text-black"
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="5" width="18" height="16" rx="2" />
              <path d="M8 3v4M16 3v4M3 10h18" />
            </svg>
          </button>
        </div>

        {/* Полоса недели: Пн–Вс, сегодня — чёрная плашка */}
        <div className="mt-6 grid grid-cols-7 gap-1.5 laptop:gap-3">
          {weekDays.map((day) => {
            const isActive = isSameDay(day, today);
            return (
              <div
                key={day.toISOString()}
                className={`flex h-14 flex-col items-center justify-center rounded-lg laptop:h-[72px]
                  ${isActive ? 'bg-black' : ''}`}
              >
                <span className={`text-lg font-semibold laptop:text-2xl ${isActive ? 'text-primary' : 'text-black'}`}>
                  {String(day.getDate()).padStart(2, '0')}
                </span>
                <span className={`text-xs laptop:text-sm ${isActive ? 'text-primary/60' : 'text-gray'}`}>
                  {WEEKDAYS[day.getDay()]}
                </span>
              </div>
            );
          })}
        </div>

        {/* QR-код */}
        <div className="mx-auto mt-10 aspect-square w-full max-w-[600px] laptop:mt-14">
          <FakeQr />
        </div>

        {/* Счётчик порций */}
        <p className="mt-8 flex items-center justify-center gap-3 pb-10 text-center text-xl font-semibold text-black laptop:mt-10 laptop:text-[32px]">
          Сегодня выдано порций:
          <span className="rounded-lg bg-accent px-4 py-1 text-xl font-semibold text-black laptop:text-[28px]">
            {issuedCount}
          </span>
        </p>
      </div>

      {/* Оверлей успеха: показывается сотруднику после выдачи */}
      {issuedStudent && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 px-5">
          <div className="flex w-full max-w-[400px] flex-col items-center rounded-2xl bg-accent px-8 py-10">
            <p className="text-center text-2xl leading-[110%] font-semibold text-black laptop:text-[32px]">
              {issuedStudent.name} ({issuedStudent.group})
            </p>
            <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="#0D0C0C" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="mt-6" aria-hidden>
              <path d="M20 6L9 17l-5-5" />
            </svg>
          </div>
        </div>
      )}
    </div>
  );
};

export default StaffQr;
